export async function enrichQueueStates(
  deps: RouteDeps,
  posts: Array<{ variants: Array<{ id: string }> }>,
) {
  await Promise.all(
    posts.flatMap((post) =>
      post.variants.map(async (variant) => {
        (variant as { queueState?: unknown }).queueState =
          await deps.publisher.getVariantQueueState(variant.id);
      }),
    ),
  );
}

